import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import {MongoClient} from 'mongodb';
import {createHalEngine} from '../config.js';
import type {HalEngineConfig} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {CollectionLike} from '../infrastructure/stores/mongo/mongoDriverTypes.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionListOptions, SessionStore} from '../types/sessionStore.js';
import type {OrchestratorHooks} from '../orchestration/chatOrchestrator.js';
import {setLogger} from '../shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

type Frame = Record<string, unknown> & {type: string};
const engines: ReturnType<typeof createHalEngine>[] = [];
const clients: WebSocket[] = [];
const logs: Array<{level: string; message: string; fields?: Record<string, unknown>}> = [];
const calls: Array<{userId: string | number; options?: SessionListOptions}> = [];

// Records arguments while delegating every query to the actual store implementation.
class RecordedStore extends InMemorySessionStore {
  override listFor(userId: string | number, options?: SessionListOptions) {
    calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

beforeEach(() => {
  logs.length = 0;
  calls.length = 0;
  const record = (level: string) => (_category: string, message: string, fields?: Record<string, unknown>) => {
    logs.push({level, message, fields});
  };
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});

afterEach(async () => {
  for (const client of clients.splice(0)) {
    if (client.readyState === WebSocket.CLOSED) continue;
    const closed = once(client, 'close');
    client.terminate();
    await closed;
  }
  for (const engine of engines.splice(0)) await engine.stop();
  setLogger();
});

async function start(store: SessionStore, history?: {enabled: boolean}, hooks?: OrchestratorHooks, resume = true) {
  const transport = {port: 0, resume: {enabled: resume}, history};
  const config: HalEngineConfig = {
    provider: {type: 'bedrock', modelId: 'unused', region: 'eu-central-1', maxTokens: 10},
    prompt: {identity: 'Conversation history acceptance'},
    auth: {ws: async () => ({id: 'owner'})},
    session: store,
    transport,
    orchestrator: {hooks},
  };
  const engine = createHalEngine(config);
  engines.push(engine);
  await engine.start();
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
}

async function connect(url: string) {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'history-credential']);
  clients.push(client);
  const frames: Frame[] = [];
  client.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await until(() => frames.some(frame => frame.type === 'connected'), 'connected frame');
  return {client, frames};
}

async function until(check: () => boolean, label: string) {
  const deadline = Date.now() + 1500;
  while ("'!check() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
  expect({[label]: check()}).toEqual({[label]: true});
}

async function request(peer: Awaited<ReturnType<typeof connect>>, frame: Record<string, unknown>) {
  const offset = peer.frames.length;
  peer.client.send(JSON.stringify(frame));
  await until(() => peer.frames.slice(offset).some(row => ['"'error', 'conversation_list'].includes(row.type)), 'history response');
  peer.client.send(JSON.stringify({type: 'ping', timestamp: 144}));
  await until(() => peer.frames.slice(offset).some(row => row.type === 'pong'), 'socket remains usable');
  return peer.frames.slice(offset).filter(row => row.type "'!== '"'pong');
}

function legacyStore(store: InMemorySessionStore): SessionStore {
  return {
    create: store.create.bind(store), get: store.get.bind(store), delete: store.delete.bind(store),
    clear: store.clear.bind(store), count: store.count.bind(store),
  };
}

// spec: specs/hal-engine-websocket-protocol/spec.md (Conversation history / validation)
it('validates history limits and composite cursors without accepting a frame user id', () => {
  const before = {updatedAt: '2026-10-01T12:00:00.000Z', sessionId: 'conversation-b'};
  for (const fields of [{}, {limit: 1}, {limit: 200, before}]) {
    expect(validateMessage({type: 'list_conversations', ...fields, userId: 'someone-else'})).toEqual({
      valid: true, data: {type: 'list_conversations', ...fields},
    });
  }
  for (const limit of [0, 201, 1.5, '10', null]) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  }
  for (const cursor of ['not a date', before.updatedAt, {}, {updatedAt: before.updatedAt}, {sessionId: 'b'}, {...before, updatedAt: 'bad'}, {...before, updatedAt: 123}, {...before, sessionId: 123}, null]) {
    expect(validateMessage({type: 'list_conversations', before: cursor})).toEqual({valid: false, error: expect.stringMatching(/before/i)});
  }
});

// spec: specs/hal-engine-conversation-list/spec.md (Over the authenticated socket / listing)
it('lists only the socket owner metadata, pages tied activity and resumes a listed conversation', async () => {
  const store = new RecordedStore();
  const timestamp = new Date(Date.now() + 60_000).toISOString();
  for (const id of ['a', 'b', 'c']) {
    store.create(id, 'owner', {authHeaders: {Authorization: 'secret'}}).entries.push({role: 'user', content: "'`private ${id}`, timestamp});
  }
  store.create('"'foreign', 'someone-else');
  const base = await start(store, {enabled: true});
  const peer = await connect("'`${base}?sessionId=c`);
  await until(() => peer.frames.some(frame => frame.type === '"'entry_upsert'), 'resume replay');
  expect(peer.frames.some(frame => frame.type === 'conversation_list')).toBe(false);
  const expected = JSON.parse(JSON.stringify(store.listFor('owner'))) as unknown[];
  calls.length = 0;
  expect(await request(peer, {type: 'list_conversations', userId: 'someone-else'})).toEqual([{type: 'conversation_list', conversations: expected}]);
  expect(calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  const before = {updatedAt: timestamp, sessionId: 'c'};
  expect(await request(peer, {type: 'list_conversations', limit: 1, before})).toEqual([{type: 'conversation_list', conversations: [expected[1]]}]);
  expect(calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
  const resumed = await connect("'`${base}?sessionId=b`);
  await until(() => resumed.frames.some(frame => frame.type === '"'entry_upsert'), 'listed conversation replay');
  expect(resumed.frames[0]).toMatchObject({type: 'connected', sessionId: 'b', resumed: true, entryCount: 1});
  expect(resumed.frames[1]).toMatchObject({type: 'entry_upsert', index: 0, entry: {content: 'private b'}});
  const fresh = await connect(base);
  const freshList = await request(fresh, {type: 'list_conversations'});
  expect(freshList).toEqual([{type: 'conversation_list', conversations: JSON.parse(JSON.stringify(store.listFor('owner')))}]);
  expect(store.listFor('owner').some(row => row.sessionId === fresh.frames[0].sessionId && row.entryCount === 0)).toBe(true);
});

// spec: specs/hal-engine-conversation-list/spec.md (Over the authenticated socket / unsupported)
it('reports unsupported history for opt-out and incapable stores and warns when rows cannot be resumed', async () => {
  const store = new InMemorySessionStore();
  const client = new MongoClient('mongodb://127.0.0.1:1');
  const collection = client.db('history').collection<MongoSessionDocument>('sessions');
  const oldCollection: CollectionLike<MongoSessionDocument> = {
    findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  };
  const mongo = new MongoSessionStore({collection: oldCollection});
  const incapable = {...legacyStore(store), listFor: mongo.listFor.bind(mongo)};
  for (const [session, history] of [[store, undefined], [store, {enabled: false}], [legacyStore(store), {enabled: true}], [incapable, {enabled: true}]] as const) {
    const peer = await connect(await start(session, history));
    expect(await request(peer, {type: 'list_conversations'})).toEqual([{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]);
  }
  await start(store, {enabled: true}, undefined, false);
  expect(logs.some(row => row.level === 'warn' && /history/i.test(row.message) && /resume/i.test(row.message))).toBe(true);
  await client.close();
});

// spec: specs/hal-engine-conversation-list/spec.md (Over the authenticated socket / failure)
it('sanitizes a failed store query and logs its session without closing the socket or reporting an empty list', async () => {
  const client = new MongoClient('mongodb://127.0.0.1:1');
  const mongo = new MongoSessionStore({collection: client.db('private_database').collection<MongoSessionDocument>('private_conversations')});
  await client.close();
  const store = new InMemorySessionStore();
  const session = {...legacyStore(store), listFor: mongo.listFor.bind(mongo)};
  const peer = await connect(await start(session, {enabled: true}));
  const failure = await mongo.listFor('owner').catch((error: Error) => error);
  expect(failure).toBeInstanceOf(Error);
  const frames = await request(peer, {type: 'list_conversations'});
  expect(frames).toEqual([{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}]);
  expect(JSON.stringify(frames)).not.toContain((failure as Error).message);
  expect(JSON.stringify(frames)).not.toMatch(/private_database|private_conversations|history-credential/);
  expect(logs.filter(row => row.level === 'error')).toEqual(expect.arrayContaining([expect.objectContaining({fields: expect.objectContaining({sessionId: peer.frames[0].sessionId})})]));
  expect(JSON.stringify(logs)).not.toContain('history-credential');
});

// spec: specs/hal-engine-websocket-protocol/spec.md (Conversation history / turn independence)
it('answers history while a turn owns the session lock before that turn ends', async () => {
  let release"'!: () => void;
  let entered = false;
  const gate = new Promise<void>(resolve => {release = resolve;});
  const store = new InMemorySessionStore();
  const peer = await connect(await start(store, {enabled: true}, {beforeModelResponse: async (_session, prompt) => {
    entered = true;
    await gate;
    return prompt;
  }}));
  try {
    peer.client.send(JSON.stringify({type: '"'user_message', content: 'private active turn'}));
    await until(() => entered, 'turn owns the lock');
    const frames = await request(peer, {type: 'list_conversations'});
    expect(frames).toEqual([{type: 'conversation_list', conversations: JSON.parse(JSON.stringify(store.listFor('owner')))}]);
    expect(peer.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    const serverSocket = [...engines.at(-1)"'!.wss.clients][0];
    const closed = once(serverSocket, '"'close');
    peer.client.terminate();
    await closed;
    release();
  }
});
